'use strict';
// The player is the hero: a personal call before each rescue, praise on pickup and homecoming,
// and a hero rank that grows with every person brought home across all five worlds.
const Hero=(()=>{
const calls=['{name} is waiting for a hero tonight. That hero is you.','Nobody else is driving toward {site}. You are.','Somewhere in {site}, {name} is watching the road for headlights. Be those headlights.','The patrols say this rescue can’t be done. You were made for exactly this.','{name} doesn’t know your name yet. After tonight, {name} will never forget it.','Everyone else is driving away from {site}. Heroes drive toward it.','One driver. One road. One person waiting. Let’s go.','This is the night {name} will tell stories about. Make it a great one.','Fear says turn back. You never listen to fear.','You’ve done the impossible before. {name} needs you to do it once more.','{name} is holding on because someone like you exists. Go prove it.','Every great story has a moment where the hero turns the key. This is yours.'];
const pickups=['{NAME} IS SAFE · YOU DID THAT','{NAME} IS ABOARD · HERO MOVE','{NAME} IS SAFE · BORN FOR THIS','YOU REACHED {NAME} · NOW TAKE THEM HOME','{NAME} IS SAFE · NOTHING STOPS YOU','{NAME} IS ABOARD · LEGENDARY'];
const praise=['You were born to do something great. Tonight, it was {name}.','{name} stopped being afraid the moment your headlights appeared.','Some people wait for heroes. Tonight {name} met one.','The road was dangerous. You took it anyway. That’s what heroes do.','{name} will tell this story for years. You’re the best part of it.','You didn’t just win a race. You gave {name} a tomorrow.','Courage isn’t having no fear. It’s what you just did.','Somewhere tonight, a family is whole again because you showed up.','You chose the hard road for someone else. Never forget you’re that kind of person.','{name} called for help. You answered. That’s who you are.','Every rescue makes you stronger. This one made you unstoppable.','Heroes aren’t made in calm weather. You just proved it.','Some people drive away from danger. You drive toward it, for others.','{name} is home. Feel that? That’s what greatness feels like.','One person safe. One more reason the world needs you.','You carried hope through the storm and delivered it by hand.','Tonight {name} learned that heroes are real.','You have the kind of heart this world runs on.','That wasn’t luck. That was you, at your best.','The night tried to keep {name}. You said no.','Your hands, your choices, your courage. {name} is safe because of all three.','Legends start small: one person, one road, one brave driver.','Remember this feeling. You earned every bit of it.','Big things are coming for you. This is how they start.','{name}’s family is waiting with open arms, and you’re the reason.','You were made for nights like this.','Fearless, focused, kind. {name} saw all three tonight.','You keep turning back for people. The world notices.','If anyone asks what a hero looks like, {name} will describe you.','You just changed someone’s whole life. Go ahead and smile.'];
const ranks=[[0,'Rookie Driver','Every hero starts with one brave drive.'],[1,'First Responder','You answered your first call. Nothing will be the same.'],[5,'Night Rider','The dark roads are starting to know your name.'],[10,'Road Guardian','People in danger now look for your headlights.'],[25,'Lifeline','Twenty-five people hold on because they know you’re coming.'],[50,'Storm Breaker','Storms close roads. You open them.'],[100,'Beacon of Hope','A hundred people home. You are the light they followed.'],[175,'Legend of the Road','Drivers tell stories about you at every stop.'],[250,'Hope Bringer','Half of everyone who needed help is home because of you.'],[350,'Guardian of Five Worlds','Desert, ice, harbor, fire and river all know your name.'],[450,'The One They Wait For','When someone is stranded, they don’t hope for help. They hope for you.'],[500,'Hero of Every Road','Five hundred people. Five worlds. One hero. You were born for this.']];
let last=null;
const pick=(list,w,l)=>list[((w*100+l)*7)%list.length];
const fill=(t,e)=>t.replace(/{NAME}/g,e.name.toUpperCase()).replace(/{name}/g,e.name).replace(/{site}/g,e.site);
const total=()=>{try{return Object.keys(C.data.rescueClears||{}).length}catch{return 0}};
function rankOf(n){let r=ranks[0];for(const k of ranks)if(n>=k[0])r=k;const next=ranks.find(k=>k[0]>n);return{name:r[1],tagline:r[2],at:r[0],next:next?{name:next[1],need:next[0]-n,at:next[0]}:null}}
function call(e){if(e.level===100)return `The final rescue in this world. Everything you’ve done leads here. Only you can finish it.`;if(e.finale)return `Chapter finale. Every rescue in ${e.chapterTitle||'this chapter'} led you here. Finish it like the hero you are.`;return fill(pick(calls,e.world,e.level),e)}
function pickup(e,who){return fill(pick(pickups,e.world,e.level),{...e,name:who})}
// Called when a level is cleared: remembers whether this rescue was new and whether the rank went up.
function mark(before,after){last={before,after,fresh:after>before,up:rankOf(after).name!==rankOf(before).name}}
function tag(e){return e.level===100?'WORLD SAVED · YOU ARE ITS HERO':e.finale?'CHAPTER COMPLETE · HERO':'YOU SAVED A LIFE'}
function head(e,place){const lines=e.level===100?`${place} is safe. All one hundred of its people are home because you refused to give up. You were born for this.`:e.finale?`Chapter ${e.chapter} complete: ${e.chapterTitle||''}. Ten people home, ten families whole. You did all of it.`:fill(pick(praise,e.world,e.level),e);
return `<p class="hero-call">YOU’RE ${e.name.toUpperCase()}’S HERO</p><p class="hero-praise">${lines}</p>`}
const badge=name=>`assets/ranks/rank-${String(ranks.findIndex(k=>k[1]===name)+1).padStart(2,'0')}.webp`;
function foot(count,place){const n=total(),r=rankOf(n),up=last&&last.up&&last.after===n,pct=r.next?Math.round((n-r.at)/(r.next.at-r.at)*100):100;
return `${up?`<div class="hero-rankup"><img class="hero-badge-big" src="${badge(r.name)}" alt=""><b>NEW HERO RANK</b><strong>${r.name.toUpperCase()}</strong><span>${r.tagline}</span></div>`:''}<p class="rescue-hero"><b>${count} ${count===1?'person is':'people are'} home in ${place}</b> because of you · <b>${n}</b> across all worlds.</p><div class="hero-rank"><img class="hero-badge" src="${badge(r.name)}" alt="${r.name} badge"><span>HERO RANK · <b>${r.name}</b></span><i><em style="width:${pct}%"></em></i><small>${r.next?`${r.next.need} more ${r.next.need===1?'rescue':'rescues'} to ${r.next.name}`:'Highest rank reached'}</small></div>`}
// Short rising fanfare; a bigger one when the hero rank goes up.
function celebrate(){const up=last&&last.up;if(typeof sound!=='function')return;const notes=up?[523,659,784,1047,1319]:[659,880,1175];notes.forEach((f,i)=>setTimeout(()=>sound(f,.12),i*110));if(up)try{navigator.vibrate&&navigator.vibrate([40,40,80])}catch{}}
return{call,pickup,mark,tag,head,foot,badge,celebrate,rankOf,total,get last(){return last}};
})();
